 1	class BinarySearch {
 2	    private static final int NOT_FOUND = -1;
 3	
 4	    static int binarySearch(int[] sortedValues, int target) {
 5	        int lowerBound = 0;
 6	        int upperBound = sortedValues.length - 1;
 7	
 8	        while (lowerBound <= upperBound) {
 9	            int mid = midpoint(lowerBound, upperBound);
10	            int midValue = sortedValues[mid];
11	
12	            if (midValue == target) {
13	                return mid;
14	            }
15	
16	            if (midValue < target) {
17	                lowerBound = mid + 1;
18	            } else {
19	                upperBound = mid - 1;
20	            }
21	        }
22	
23	        return NOT_FOUND;
24	    }
25	
26	    public static void main(String[] args) {
27	        BinarySearchDemo.run();
28	    }
29	
30	    private static int midpoint(int lowerBound, int upperBound) {
31	        return lowerBound + (upperBound - lowerBound) / 2;
32	    }
33	
34	    static boolean isFoundIndex(int index) {
35	        return index != NOT_FOUND;
36	    }
37	}

